fragmentGLSL:
#version 330
// ======================================================
// Processed shader effects/basic
// ======================================================
precision highp float;
#define mul(x, y) ((y) * (x))
#define max(x, y) max (y, x)
#define lerp mix
#define frac fract
#define CASTU(x) (uint(x))
#define CAST2(x) (vec2(x))
#define CAST3(x) (vec3(x))
#define CAST4(x) (vec4(x))
#define CAST3X3(x) (mat3(x))
#define saturate(x) (clamp(x, 0.0, 1.0))
#define texSample2D texture
#define texSample2DLod textureLod
#define DECLARE_SAMPLER2D_PARAMETER(name) sampler2D name
#define MAKE_SAMPLER2D_ARGUMENT(name) name
#define log10(x) log2(x) * 0.301029995663981
#define atan2 atan
#define fmod(x, y) ((x)-(y)*trunc((x)/(y)))
#define ddx dFdx
#define ddy(x) dFdy(-(x))
#define GLSL 1
#define float2 vec2
#define float3 vec3
#define float4 vec4
#define half2 vec2
#define half3 vec3
#define half4 vec4
#define float3x3 mat3
#define float4x4 mat4
#define float2x2 mat2
#define gl_FragColor out_FragColor
out vec4 out_FragColor;
#define varying in
#define AA_CATEGORY 1
#define GMODE 2
varying vec2 v_TexCoord;
uniform sampler2D g_Texture0; // {"default":"materials/test"}
uniform vec4 g_Tint; // Added for layer scale correction
// [COMBO] {"combo":"AA_CATEGORY","type":"options","default":0,"options":{Color:0,"UV":1}}
// begin of require libs/noise
float sampleNoise(vec2 uv) {
    return fract(uv.x + uv.y);
}

// end of require libs/noise

void main() {
    vec3 noise = vec3(sampleNoise(v_TexCoord), 0.0, 0.0);
    out_FragColor = texture(g_Texture0, v_TexCoord) + vec4(noise, 1.0) + g_Tint * 0.0;
}

metal.fragmentMSL:
#pragma clang diagnostic ignored "-Wmissing-prototypes"

#include <metal_stdlib>
#include <simd/simd.h>

using namespace metal;

struct main0_out
{
    float4 out_FragColor;
};

struct main0_in
{
    float2 v_TexCoord;
};

static inline __attribute__((always_inline))
float sampleNoise(thread const float2& uv)
{
    return fract(uv.x + uv.y);
}

fragment main0_out main0(main0_in in [[stage_in]], constant float4& g_Tint [[buffer(0)]], texture2d<float> g_Texture0 [[texture(0)]], sampler g_Texture0Smplr [[sampler(0)]])
{
    main0_out out = {};
    float2 param = in.v_TexCoord;
    float3 _noise = float3(sampleNoise(param), 0.0, 0.0);
    out.out_FragColor = (g_Texture0.sample(g_Texture0Smplr, in.v_TexCoord) + float4(_noise, 1.0)) + (g_Tint * 0.0);
    return out;
}

metal.vertexMSL:
#pragma clang diagnostic ignored "-Wmissing-prototypes"

#include <metal_stdlib>
#include <simd/simd.h>

using namespace metal;

struct main0_out
{
    float2 v_TexCoord;
    float4 gl_Position [[position]];
};

struct main0_in
{
    float3 a_Position [[attribute(0)]];
};

static inline __attribute__((always_inline))
float2 computeUV(thread const float2& inputUV)
{
    return (inputUV * 0.5) + float2(0.5);
}

vertex main0_out main0(main0_in in [[stage_in]])
{
    main0_out out = {};
    float2 param = in.a_Position.xy;
    out.v_TexCoord = computeUV(param);
    out.gl_Position = float4(in.a_Position, 1.0);
    return out;
}
